/// ASCII文字列をランレングス圧縮
/// "aaabbcaaaa" → [(b'a', 3), (b'b', 2), (b'c', 1), (b'a', 4)]
#[inline(always)]
pub fn run_length_encode(s: &str) -> Vec<(u8, usize)> {
    let bytes = s.as_bytes();
    let n = bytes.len();

    if n == 0 {
        return Vec::new();
    }

    // 最大サイズを確保して再確保をなしに
    let mut result = Vec::<(u8, usize)>::with_capacity(n);
    let mut current = bytes[0];
    let mut count = 1_usize;
    for &byte in &bytes[1..] {
        // 同じならカウント
        if byte == current {
            count += 1;
        }
        // 違うなら次
        else {
            result.push((current, count));

            current = byte;
            count = 1;
        }
    }
    result.push((current, count));
    return result;
} // end of run_length_encode

/// 任意のスライスをランレングス圧縮
#[inline(always)]
pub fn run_length_encode_slice<T>(values: &[T]) -> Vec<(T, usize)>
where
    T: Copy + Eq,
{
    let n = values.len();
    if n == 0 {
        return Vec::new();
    }

    let mut result = Vec::<(T, usize)>::with_capacity(n);
    let mut current = values[0];
    let mut count = 1_usize;

    for &value in &values[1..] {
        if value == current {
            count += 1;
        } else {
            result.push((current, count));

            current = value;
            count = 1;
        }
    }
    result.push((current, count));
    return result;
} // end of run_length_encode_slice
